/*
 * Nota de voz (2026-10-06, /tania-canal-propio 4 «la carta habla») — la grabadora del navegador, GENÉRICA: nada de la casa adentro,
 * la monta el widget de Tania y la puede montar Luzpass. Jorge, 2026-10-03: «fomentar que hagan su pedido rápido con nota de voz
 * desde el sitio web».
 *  · Formato: el que el navegador SÍ graba (LibreChat useSpeechToTextExternal · getBestSupportedMimeType, MIT): Chrome/Firefox
 *    WebM/Opus; iOS Safari audio/mp4 (AAC; WebM sólo desde Safari 18.4). El Blob lleva el tipo REAL del MediaRecorder (deep-chat
 *    lo etiquetaba con el pedido y en Safari mentía). Whisper (Workers AI) transcribe webm, mp4, ogg y wav igual (medido 10-06).
 *  · Nivel: un AnalyserNode mide el volumen para que la persona VEA que se le oye (alNivel 0..1, ~60 por segundo).
 *  · Tope: maxMs (12 s por defecto, como Panera); al tope se para sola y entrega.
 *  · El AudioContext nace dentro del gesto (iOS sólo lo deja sonar así); el micrófono se suelta al terminar, siempre.
 *
 *   NotaDeVoz.soportado()                      → ¿hay micrófono + MediaRecorder en un contexto seguro?
 *   NotaDeVoz.graba({maxMs, alEmpezar, alNivel, alTerminar(blob, {ms, pico, mime}), alFallar(motivo)}) → {para(), cancela()}
 *       motivo: 'sin_permiso' | 'sin_micro' | 'grabadora' | 'cancelada'
 *   NotaDeVoz.base64(blob)                     → Promise<string> (sin el prefijo data:)
 */
(function () {
  if (typeof window === "undefined" || window.NotaDeVoz) return;
  var CANDIDATOS = ["audio/webm;codecs=opus", "audio/webm", "audio/mp4", "audio/ogg;codecs=opus", "audio/ogg", "audio/wav"];
  function mime() {
    if (typeof MediaRecorder === "undefined" || typeof MediaRecorder.isTypeSupported !== "function") return "";
    for (var i = 0; i < CANDIDATOS.length; i++) {
      try { if (MediaRecorder.isTypeSupported(CANDIDATOS[i])) return CANDIDATOS[i]; } catch (e) {}
    }
    return "";
  }
  function soportado() {
    return !!(window.isSecureContext !== false && navigator.mediaDevices && typeof navigator.mediaDevices.getUserMedia === "function" &&
      typeof MediaRecorder !== "undefined");
  }
  function graba(o) {
    o = o || {};
    var rec = null, stream = null, ac = null, raf = 0, corte = 0, t0 = 0, pico = 0, trozos = [], cancelada = false, fin = false;
    function suelta() {
      if (raf) cancelAnimationFrame(raf);
      clearTimeout(corte);
      try { if (stream) stream.getTracks().forEach(function (t) { t.stop(); }); } catch (e) {}
      try { if (ac && ac.state !== "closed") ac.close(); } catch (e) {}
    }
    function falla(m) { if (fin) return; fin = true; suelta(); if (o.alFallar) o.alFallar(m); }
    var h = {
      para: function () { if (rec && rec.state !== "inactive") { try { rec.stop(); } catch (e) { falla("grabadora"); } } },
      cancela: function () { cancelada = true; if (rec && rec.state !== "inactive") h.para(); else if (!rec) falla("cancelada"); },
    };
    try { var AC = window.AudioContext || window.webkitAudioContext; if (AC) ac = new AC(); } catch (e) { ac = null; }
    navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } }).then(function (s) {
      stream = s;
      // cancelada mientras el navegador pedía permiso: el micrófono se suelta de inmediato (falla avisa una sola vez)
      if (cancelada || fin) { if (fin) suelta(); else falla("cancelada"); return; }
      var m = mime();
      // 32 kbps basta para la voz y la nota pesa ~¼ (medido 10-07: 71 KB → 19 KB, Whisper igual de bien y no más lento):
      // en un teléfono con red móvil la subida es lo que tarda
      try { rec = m ? new MediaRecorder(s, { mimeType: m, audioBitsPerSecond: 32000 }) : new MediaRecorder(s, { audioBitsPerSecond: 32000 }); } catch (e) {
        try { rec = m ? new MediaRecorder(s, { mimeType: m }) : new MediaRecorder(s); } catch (e2) { falla("grabadora"); return; }
      }
      rec.ondataavailable = function (e) { if (e.data && e.data.size) trozos.push(e.data); };
      rec.onstop = function () {
        if (fin) return;
        fin = true;
        var ms = Date.now() - t0;
        suelta();
        if (cancelada) { if (o.alFallar) o.alFallar("cancelada"); return; }
        var tipo = String(rec.mimeType || m || "audio/webm");
        if (o.alTerminar) o.alTerminar(new Blob(trozos, { type: tipo }), { ms: ms, pico: pico, mime: tipo });
      };
      if (ac) {
        try {
          if (ac.state === "suspended" && ac.resume) ac.resume();
          var an = ac.createAnalyser();
          an.fftSize = 512;
          ac.createMediaStreamSource(s).connect(an);
          var buf = new Uint8Array(an.fftSize);
          (function mide() {
            an.getByteTimeDomainData(buf);
            var suma = 0;
            for (var i = 0; i < buf.length; i++) { var x = (buf[i] - 128) / 128; suma += x * x; }
            var nivel = Math.min(1, Math.sqrt(suma / buf.length) * 4);
            if (nivel > pico) pico = nivel;
            if (o.alNivel) o.alNivel(nivel);
            raf = requestAnimationFrame(mide);
          })();
        } catch (e) {}
      }
      t0 = Date.now();
      try { rec.start(250); } catch (e) { falla("grabadora"); return; }
      corte = setTimeout(h.para, o.maxMs || 12000);
      if (o.alEmpezar) o.alEmpezar();
    }, function (err) {
      var n = err && err.name;
      falla(n === "NotAllowedError" || n === "SecurityError" ? "sin_permiso" : "sin_micro");
    });
    return h;
  }
  function base64(blob) {
    return new Promise(function (ok, no) {
      var r = new FileReader();
      r.onload = function () { var s = String(r.result || ""); ok(s.slice(s.indexOf(",") + 1)); };
      r.onerror = function () { no(r.error); };
      r.readAsDataURL(blob);
    });
  }
  window.NotaDeVoz = { soportado: soportado, mime: mime, graba: graba, base64: base64 };
})();
